import React, { useEffect, useState, useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { healthService, animalService } from '../services/api';
import toast from 'react-hot-toast';
import { Plus } from 'lucide-react';


const RECORD_TYPES = {
  vaccination: { label: 'Aşı', color: 'bg-blue-100 text-blue-700' },
  medication: { label: 'İlaç', color: 'bg-green-100 text-green-700' },
  examination: { label: 'Muayene', color: 'bg-purple-100 text-purple-700' },
  disease: { label: 'Hastalık', color: 'bg-red-100 text-red-700' },
  surgery: { label: 'Cerrahi', color: 'bg-orange-100 text-orange-700' }
};

export default function HealthPage() {
  const { user } = useAuth();
  const farmId = user?.farm_id;
  const [searchParams] = useSearchParams();
  const initialAnimalId = searchParams.get('animal_id') || '';

  const [records, setRecords] = useState([]);
  const [animals, setAnimals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({ record_type: '', animal_id: initialAnimalId, from: '', to: '' });
  const [showForm, setShowForm] = useState(!!initialAnimalId);
  const [form, setForm] = useState({
    animal_id: initialAnimalId, record_type: 'vaccination',
    record_date: new Date().toISOString().split('T')[0],
    description: '', medication_name: '', dosage: '',
    veterinarian_id: null, cost: '', notes: ''
  });

  const load = useCallback(async () => {
    if (!farmId) return;
    setLoading(true);
    try {
      const [res, animRes] = await Promise.allSettled([
        healthService.list(farmId, filters),
        animalService.list(farmId, 1, 100, { status: 'active' })
      ]);
      if (res.status === 'fulfilled') setRecords(res.value.data?.data || []);
      if (animRes.status === 'fulfilled') setAnimals(animRes.value.data?.data || []);
    } catch {
      toast.error('Sağlık kaydı yüklenemedi');
      setRecords([]);
    } finally {
      setLoading(false);
    }
  }, [farmId, filters]);

  useEffect(() => {
    load();
  }, [load]);

  const handleAdd = async (e) => {
    e.preventDefault();
    if (!form.animal_id || !form.record_date) {
      toast.error('Hayvan ve tarih zorunlu');
      return;
    }
    try {
      await healthService.create(farmId, form);
      toast.success('Sağlık kaydı eklendi');
      setShowForm(false);
      setForm({
        animal_id: '', record_type: 'vaccination',
        record_date: new Date().toISOString().split('T')[0],
        description: '', medication_name: '', dosage: '',
        veterinarian_id: null, cost: '', notes: ''
      });
      load();
    } catch (err) {
      toast.error(err.response?.data?.error || 'İşlem başarısız');
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">💊 Sağlık Yönetimi</h1>
          <p className="text-sm text-gray-500">Aşı, ilaç ve tedavi kayıtları</p>
        </div>
        <button onClick={() => setShowForm(!showForm)} className={`btn-primary flex items-center justify-center gap-2 ${showForm ? 'bg-red-500 hover:bg-red-600' : ''}`}>
          {showForm ? 'İptal' : <><Plus className="w-4 h-4" /> Kayıt Ekle</>}
        </button>
      </div>

      {/* Form */}
      {showForm && (
        <div className="card border-purple-100 bg-purple-50/20 animate-in fade-in slide-in-from-top-4">
          <h2 className="text-lg font-bold mb-4 text-purple-900">Yeni Sağlık Kaydı</h2>
          <form onSubmit={handleAdd} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Hayvan Seçin</label>
                <select
                  value={form.animal_id}
                  onChange={e => setForm({ ...form, animal_id: e.target.value })}
                  className="input-field"
                  required
                >
                  <option value="">Hayvan Seçin...</option>
                  {animals.map(a => (
                    <option key={a.id} value={a.id}>
                      {a.name} ({a.code}) - {a.species}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Kayıt Türü</label>
                <select
                  value={form.record_type}
                  onChange={e => setForm({ ...form, record_type: e.target.value })}
                  className="input-field"
                >
                  {Object.entries(RECORD_TYPES).map(([k, v]) => (
                    <option key={k} value={k}>{v.label}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Kayıt Tarihi</label>
                <input
                  type="date"
                  value={form.record_date}
                  onChange={e => setForm({ ...form, record_date: e.target.value })}
                  className="input-field"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">İlaç / Aşı Adı</label>
                <input
                  type="text"
                  placeholder="Örn: Parazit aşısı"
                  value={form.medication_name}
                  onChange={e => setForm({ ...form, medication_name: e.target.value })}
                  className="input-field"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Dozaj</label>
                <input
                  type="text"
                  placeholder="Örn: 2ml"
                  value={form.dosage}
                  onChange={e => setForm({ ...form, dosage: e.target.value })}
                  className="input-field"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Maliyet (₺)</label>
                <input
                  type="number"
                  placeholder="0.00"
                  value={form.cost}
                  onChange={e => setForm({ ...form, cost: e.target.value })}
                  className="input-field"
                />
              </div>
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Açıklama / Tanı</label>
              <textarea
                placeholder="Tedavi veya muayene detaylarını buraya yazın..."
                value={form.description}
                onChange={e => setForm({ ...form, description: e.target.value })}
                className="input-field"
                rows={2}
              />
            </div>
            <div className="flex gap-3">
              <button type="button" onClick={() => setShowForm(false)} className="btn-secondary flex-1">Vazgeç</button>
              <button type="submit" className="btn-primary flex-1">Kaydı Kaydet</button>
            </div>
          </form>
        </div>
      )}

      {/* Filtreler */}
      <div className="card p-4">
        <div className="flex flex-col md:flex-row gap-3">
          <select
            value={filters.record_type}
            onChange={e => { setFilters({ ...filters, record_type: e.target.value }); }}
            className="input-field flex-1"
          >
            <option value="">Tüm Kayıt Türleri</option>
            {Object.entries(RECORD_TYPES).map(([k, v]) => (
              <option key={k} value={k}>{v.label}</option>
            ))}
          </select>
          <input
            type="date"
            value={filters.from}
            onChange={e => setFilters({ ...filters, from: e.target.value })}
            className="input-field flex-1"
          />
          <button onClick={load} className="btn-secondary px-8">Filtrele</button>
        </div>
      </div>

      {/* Kayıt Listesi */}
      <div className="card p-0 overflow-hidden">
        <div className="overflow-x-auto">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <div className="w-8 h-8 border-4 border-purple-600 border-t-transparent rounded-full animate-spin" />
            </div>
          ) : records.length === 0 ? (
            <div className="text-center py-12 text-gray-400">
              <div className="text-4xl mb-2">💊</div>
              <p className="font-medium text-sm">Sağlık kaydı bulunamadı</p>
            </div>
          ) : (
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Tarih</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Tür</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Tanı / İlaç</th>
                  <th className="text-right px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Maliyet</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {records.map(r => (
                  <tr key={r.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap text-gray-600">{r.record_date}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider ${RECORD_TYPES[r.record_type]?.color}`}>
                        {RECORD_TYPES[r.record_type]?.label}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                       <p className="font-bold text-gray-900 truncate max-w-xs">{r.medication_name || r.description || '—'}</p>
                       <p className="text-[10px] text-gray-500 font-medium uppercase">
                         {r.animal?.name ? `${r.animal.name} (${r.animal.code})` : `Hayvan #${r.animal_id}`}
                       </p>
                    </td>
                    <td className="px-6 py-4 text-right font-black text-gray-900">
                       {r.cost ? `₺${r.cost.toLocaleString('tr-TR')}` : '—'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}